CREATE TABLE IF NOT EXISTS identity_provider_settings (id TEXT PRIMARY KEY CHECK(id='default'), mode TEXT NOT NULL DEFAULT 'internal' CHECK(mode IN ('internal','hybrid')), tenant_id TEXT, client_id TEXT, issuer TEXT, updated_by TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); INSERT OR IGNORE INTO identity_provider_settings(id,mode) VALUES('default','internal'); CREATE TABLE IF NOT EXISTS federated_identities (provider TEXT NOT NULL, issuer TEXT NOT NULL, subject TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), linked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(provider,issuer,subject), UNIQUE(provider,user_id)); CREATE TABLE IF NOT EXISTS oidc_login_states (state_hash TEXT PRIMARY KEY, nonce_hash TEXT NOT NULL, code_verifier TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);